customCSS:
.t, .history { color: #928374; }
.join { color: #a9b665; }
.part, .quit { color: #928374; }
.kick, .error { color: #ea6962; }
.notice { color: #d8a657; }
.action { color: #d3869b; }
.mode, .nick, .topic, .server { color: #89b482; }
.highlight { color: #d4be98; background-color: #45403d; border-left: 3px solid #d3869b; padding-left: 8px; }
.reply { color: #928374; border-left: 2px solid #7daea3; padding-left: 6px; }
.oper { color: #282828; background-color: #d8a657; }
.reactions { color: #7daea3; background-color: #32302f; }
.card { background-color: #32302f; border-color: #928374; }
.card-title { color: #7daea3; }
.card-desc { color: #928374; }
.daychange { color: #928374; border-color: #32302f; }
